package com.tzjakejad.intelligencegathering;

import java.awt.Color;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(IntelligenceGatheringConfig.GROUP)
public interface IntelligenceGatheringConfig extends Config
{
	String GROUP = "intelligence-gathering";

	@ConfigSection(
		name = "Tracking",
		description = "Which areas to track from the notice board",
		position = 0
	)
	String trackingSection = "tracking";

	@ConfigSection(
		name = "Navigation",
		description = "World map, minimap and tile markers",
		position = 1
	)
	String navigationSection = "navigation";

	@ConfigSection(
		name = "Combat",
		description = "Gangster and boss highlighting",
		position = 2
	)
	String combatSection = "combat";

	@ConfigSection(
		name = "Timers",
		description = "Rotation and despawn infoboxes",
		position = 3
	)
	String timersSection = "timers";

	@ConfigSection(
		name = "Data",
		description = "Rotation logging",
		position = 4
	)
	String dataSection = "data";

	@ConfigSection(
		name = "Rewards",
		description = "Guards on the reward XP dialog",
		position = 5
	)
	String rewardsSection = "rewards";

	// ------------------------------------------------------------------ Tracking

	@ConfigItem(
		keyName = "multiCombatOnly",
		name = "Multicombat only",
		description = "Only show meetings in multicombat areas",
		section = trackingSection,
		position = 0
	)
	default boolean multiCombatOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "trackArceuus",
		name = "Track Arceuus",
		description = "Show meetings in the Arceuus area",
		section = trackingSection,
		position = 1
	)
	default boolean trackArceuus()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackHosidius",
		name = "Track Hosidius",
		description = "Show meetings in the Hosidius area",
		section = trackingSection,
		position = 2
	)
	default boolean trackHosidius()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackLovakengj",
		name = "Track Lovakengj",
		description = "Show meetings in the Lovakengj area",
		section = trackingSection,
		position = 3
	)
	default boolean trackLovakengj()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackPiscarilius",
		name = "Track Piscarilius",
		description = "Show meetings in the Port Piscarilius area",
		section = trackingSection,
		position = 4
	)
	default boolean trackPiscarilius()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackShayzien",
		name = "Track Shayzien",
		description = "Show meetings in the Shayzien area",
		section = trackingSection,
		position = 5
	)
	default boolean trackShayzien()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackOther",
		name = "Track Other",
		description = "Show meetings in other Kourend locations",
		section = trackingSection,
		position = 6
	)
	default boolean trackOther()
	{
		return true;
	}

	// ---------------------------------------------------------------- Navigation

	@ConfigItem(
		keyName = "showWorldMapMarker",
		name = "World map marker",
		description = "Drop a marker on the world map at the current meeting spawn",
		section = navigationSection,
		position = 0
	)
	default boolean showWorldMapMarker()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTileHighlight",
		name = "Tile highlight",
		description = "Highlight the spawn tiles when in the meeting region",
		section = navigationSection,
		position = 2
	)
	default boolean showTileHighlight()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHintArrow",
		name = "Hint arrow to meeting",
		description = "Point the game hint arrow at the meeting. Shows on the minimap (clamped to the "
			+ "edge when far) and in the world, at any distance or floor. Only one hint arrow exists "
			+ "globally, so it competes with other plugins that use it.",
		section = navigationSection,
		position = 3
	)
	default boolean showHintArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tileColor",
		name = "Tile colour",
		description = "Colour of the scene tile highlight",
		section = navigationSection,
		position = 4
	)
	default Color tileColor()
	{
		return new Color(0, 200, 255);
	}

	@ConfigItem(
		keyName = "routeViaShortestPath",
		name = "Route via Shortest Path",
		description = "If the Shortest Path plugin is installed, draw a walking route to the meeting. "
			+ "The map pin and tile highlight always work regardless of this setting.",
		section = navigationSection,
		position = 6
	)
	default boolean routeViaShortestPath()
	{
		return false;
	}

	// -------------------------------------------------------------------- Combat

	@ConfigItem(
		keyName = "highlightGangsters",
		name = "Highlight gangsters",
		description = "Outline gangster NPCs at the meeting",
		section = combatSection,
		position = 0
	)
	default boolean highlightGangsters()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightBoss",
		name = "Highlight boss",
		description = "Highlight the gang boss distinctly (always drops intelligence)",
		section = combatSection,
		position = 1
	)
	default boolean highlightBoss()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bossHighlightStyle",
		name = "Highlight style",
		description = "How to render the gangster and boss highlights",
		section = combatSection,
		position = 2
	)
	default BossHighlightStyle bossHighlightStyle()
	{
		return BossHighlightStyle.OUTLINE;
	}

	@ConfigItem(
		keyName = "gangsterColor",
		name = "Gangster colour",
		description = "Highlight colour for gangster NPCs",
		section = combatSection,
		position = 3
	)
	default Color gangsterColor()
	{
		return new Color(255, 220, 0);
	}

	@ConfigItem(
		keyName = "bossColorDangerous",
		name = "Boss colour (dangerous)",
		description = "Boss outline when it throws knives (male / ranged / dangerous)",
		section = combatSection,
		position = 4
	)
	default Color bossColorDangerous()
	{
		return new Color(200, 60, 60);
	}

	@ConfigItem(
		keyName = "bossColorSafe",
		name = "Boss colour (safe)",
		description = "Boss outline when it fights with a cutlass (female / melee / safe)",
		section = combatSection,
		position = 5
	)
	default Color bossColorSafe()
	{
		return new Color(60, 170, 60);
	}

	@ConfigItem(
		keyName = "bossColor",
		name = "Boss colour (unknown)",
		description = "Boss outline before its combat style has been seen; classified bosses use the "
			+ "dangerous/safe colours above",
		section = combatSection,
		position = 6
	)
	default Color bossColor()
	{
		return new Color(255, 90, 0);
	}

	@ConfigItem(
		keyName = "safeWorldsOnly",
		name = "Safe worlds only",
		description = "Hide worlds with a male (dangerous) boss in the hop list",
		section = combatSection,
		position = 7
	)
	default boolean safeWorldsOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightIntel",
		name = "Highlight dropped intelligence",
		description = "Highlight Shayzien gang intelligence (the boss drop) while it's on the ground",
		section = combatSection,
		position = 8
	)
	default boolean highlightIntel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "intelColor",
		name = "Intelligence colour",
		description = "Highlight colour for dropped intelligence",
		section = combatSection,
		position = 9
	)
	default Color intelColor()
	{
		return new Color(190, 80, 255);
	}

	// -------------------------------------------------------------------- Timers

	@ConfigItem(
		keyName = "showDespawnTimer",
		name = "Despawn timer",
		description = "Infobox counting down the 5-minute despawn window",
		section = timersSection,
		position = 0
	)
	default boolean showDespawnTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRotationTimer",
		name = "Meeting start timer",
		description = "Infobox counting down until the gang meeting starts (matches the notice board)",
		section = timersSection,
		position = 1
	)
	default boolean showRotationTimer()
	{
		return true;
	}

	// ---------------------------------------------------------------------- Data

	@ConfigItem(
		keyName = "logRotations",
		name = "Log rotations",
		description = "Append observed (timestamp, location) rows to rotations.csv for analysis",
		section = dataSection,
		position = 0
	)
	default boolean logRotations()
	{
		return false;
	}

	// ------------------------------------------------------------------- Rewards

	@ConfigItem(
		keyName = "lockXpReward",
		name = "Lock reward XP skills",
		description = "Ignore clicks on skills you have not allowed in the \"What kind of training will you pursue?\" dialog",
		section = rewardsSection,
		position = 0
	)
	default boolean lockXpReward()
	{
		return false;
	}

	@ConfigItem(
		keyName = "allowedXpSkills",
		name = "Allowed skills",
		description = "Skills that stay clickable. Ctrl-click to pick more than one; selecting none blocks every skill",
		section = rewardsSection,
		position = 1
	)
	default Set<RewardSkill> allowedXpSkills()
	{
		return EnumSet.of(RewardSkill.DEFENCE);
	}

	enum BossHighlightStyle
	{
		HULL,
		TILE,
		OUTLINE
	}

	/**
	 * The four skills the reward dialog offers, in the order it lists them. Deliberately not the
	 * full skill list: the chest only ever trains combat, and a longer list would just be noise to
	 * scroll past. Constant names must match the skill named in the dialog row, which is how
	 * {@code XpRewardLock} pairs an option with its entry here.
	 */
	enum RewardSkill
	{
		ATTACK,
		STRENGTH,
		DEFENCE,
		HITPOINTS;

		@Override
		public String toString()
		{
			return name().charAt(0) + name().substring(1).toLowerCase(java.util.Locale.ROOT);
		}
	}
}

package com.tzjakejad.intelligencegathering;

import com.google.inject.Provides;
import com.tzjakejad.intelligencegathering.board.NoticeBoardReader;
import com.tzjakejad.intelligencegathering.combat.GangIds;
import com.tzjakejad.intelligencegathering.combat.GroundItemOverlay;
import com.tzjakejad.intelligencegathering.combat.NpcHighlightOverlay;
import com.tzjakejad.intelligencegathering.data.MeetingStore;
import com.tzjakejad.intelligencegathering.data.RotationLogger;
import com.tzjakejad.intelligencegathering.data.ShareCode;
import com.tzjakejad.intelligencegathering.model.BossGender;
import com.tzjakejad.intelligencegathering.model.CurrentMeeting;
import com.tzjakejad.intelligencegathering.model.OcLocation;
import com.tzjakejad.intelligencegathering.model.WorldStatus;
import com.tzjakejad.intelligencegathering.hop.WorldHopper;
import com.tzjakejad.intelligencegathering.nav.SceneOverlay;
import com.tzjakejad.intelligencegathering.nav.WorldMapController;
import com.tzjakejad.intelligencegathering.rewards.XpRewardLock;
import com.tzjakejad.intelligencegathering.timer.MeetingTimers;
import com.tzjakejad.intelligencegathering.ui.IntelligenceGatheringController;
import com.tzjakejad.intelligencegathering.ui.IntelligenceGatheringPanel;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentSkipListMap;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Intelligence Gathering",
	description = "Finds the current Shayzien organised crime meeting and points you to it",
	tags = {"intelligence", "organised", "organized", "crime", "shayzien", "kourend", "gang"}
)
public class IntelligenceGatheringPlugin extends Plugin implements IntelligenceGatheringController
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private IntelligenceGatheringConfig config;

	@Inject
	private NoticeBoardReader boardReader;

	@Inject
	private WorldMapController worldMapController;

	@Inject
	private SceneOverlay sceneOverlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MeetingTimers meetingTimers;

	@Inject
	private WorldHopper worldHopper;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private EventBus eventBus;

	@Inject
	private RotationLogger rotationLogger;

	@Inject
	private MeetingStore meetingStore;

	@Inject
	private GangIds gangIds;

	@Inject
	private NpcHighlightOverlay npcHighlightOverlay;

	@Inject
	private GroundItemOverlay groundItemOverlay;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private XpRewardLock xpRewardLock;

	@Inject
	private ShareCode shareCode;

	@Getter
	private volatile CurrentMeeting currentMeeting;

	/** Worlds visited during the current cycle, keyed by world number. */
	private final Map<Integer, WorldStatus> worldStatuses = new ConcurrentSkipListMap<>();

	/** Tracked meeting NPCs for the highlight overlay (spec §4); mutated on the client thread. */
	private final Set<NPC> gangsters = ConcurrentHashMap.newKeySet();
	private final Set<NPC> bosses = ConcurrentHashMap.newKeySet();

	/** Tiles holding dropped gang intelligence (item 13395), for the ground highlight. */
	private final Set<Tile> intelTiles = ConcurrentHashMap.newKeySet();

	/**
	 * Present in all 34 known board messages and specific enough that no other interface trips it.
	 * Gates the full match so the board can be found without hardcoding which interface renders it.
	 */
	private static final Pattern BOARD_SENTINEL = Pattern.compile("received\\s+reports", Pattern.CASE_INSENSITIVE);

	/**
	 * A message box has to be saying there is nothing, not merely talking about gangs, before it
	 * is allowed to clear a meeting. Word boundaries keep "no" from matching inside "north".
	 */
	private static final Pattern NO_MEETING = Pattern.compile(
		"\\b(no|not|none|nothing|never|empty|quiet|aren't|isn't|haven't|hasn't|don't)\\b",
		Pattern.CASE_INSENSITIVE);

	/**
	 * Last board read the tracking filters discarded, kept only so the panel can say why it is empty.
	 * Held alongside the reason and expired with its own rotation window.
	 */
	private volatile CurrentMeeting excludedMeeting;
	private volatile String excludedReason;

	/** Last target posted to Shortest Path, for the §2 debounce. */
	private WorldPoint lastRouted;

	/** World seen on the previous game tick; the panel is only rebuilt when it changes. */
	private int lastWorld = -1;

	private BufferedImage markerIcon;
	/** Intelligence item sprite for the despawn infobox; null until fetched on the client thread. */
	private volatile BufferedImage intelIcon;
	private BufferedImage worldMapIcon;
	private IntelligenceGatheringPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		markerIcon = buildIcon();
		// Reuse the plugin badge for the world-map marker, scaled down to a legible marker size.
		worldMapIcon = ImageUtil.resizeImage(markerIcon, 32, 32);
		sceneOverlay.setMeetingSupplier(this::getCurrentMeeting);
		overlayManager.add(sceneOverlay);

		npcHighlightOverlay.setGangsterSupplier(() -> gangsters);
		npcHighlightOverlay.setBossSupplier(() -> bosses);
		overlayManager.add(npcHighlightOverlay);

		groundItemOverlay.setTileSupplier(() -> intelTiles);
		overlayManager.add(groundItemOverlay);

		panel = new IntelligenceGatheringPanel(this, skillIconManager);
		navButton = NavigationButton.builder()
			.tooltip("Intelligence Gathering")
			.icon(markerIcon)
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// Restore on the client thread: it touches client state (hint arrow, Shortest Path) and
		// startUp runs on the Swing thread when the plugin is toggled from the config panel.
		clientThread.invokeLater(() ->
		{
			intelIcon = itemManager.getImage(ItemID.SHAYZIEN_GANG_INTELLIGENCE);
			restoreState();
		});

		log.info("Intelligence Gathering started");
	}

	/** Restore a persisted meeting + hop list (spec §6) if the saved cycle is still live. */
	private void restoreState()
	{
		MeetingStore.Restored restored = meetingStore.load();
		if (restored == null)
		{
			return;
		}

		currentMeeting = restored.getMeeting();
		worldStatuses.clear();
		for (WorldStatus ws : restored.getWorlds())
		{
			worldStatuses.put(ws.getWorld(), ws);
		}

		OcLocation location = restored.getMeeting().getLocation();
		applyWorldMapMarker();
		updateHintArrow();
		routeTo(location.getWorldPoint());
		meetingTimers.update(currentMeeting, config, this, markerIcon, despawnIcon());
		refreshPanel();
		log.debug("Restored organised crime meeting: {}", location.getId());
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(npcHighlightOverlay);
		overlayManager.remove(groundItemOverlay);
		clientToolbar.removeNavigation(navButton);
		worldMapController.clear();
		meetingTimers.clear();
		client.clearHintArrow();
		clearRoute();
		// Keep the persisted meeting so a restart mid-cycle restores it (spec §6); just drop the
		// in-memory copy and any tracked NPCs.
		currentMeeting = null;
		worldStatuses.clear();
		gangsters.clear();
		bosses.clear();
		intelTiles.clear();
		lastWorld = -1;
		intelIcon = null;
		panel = null;
		navButton = null;
		log.info("Intelligence Gathering stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.HOPPING || state == GameState.LOADING
			|| state == GameState.LOGGING_IN || state == GameState.LOGIN_SCREEN
			|| state == GameState.CONNECTION_LOST)
		{
			// NPC indices from the old scene are now invalid, and RuneLite doesn't reliably fire
			// NpcDespawned for them on a hop/teardown — drop the tracked references so their outlines
			// (and ground-item tiles) don't ghost onto the new world. LOADING covers same-world region
			// changes, which reshuffle NPC indices without passing through HOPPING. They re-populate
			// from the NpcSpawned/ItemSpawned events that re-fire once the new scene finishes loading.
			gangsters.clear();
			bosses.clear();
			intelTiles.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		worldHopper.processPendingHop();
		xpRewardLock.markLockedOptions();

		CurrentMeeting meeting = currentMeeting;

		CurrentMeeting excluded = excludedMeeting;
		if (excluded != null && excluded.rotationEndMs() <= System.currentTimeMillis())
		{
			excludedMeeting = null;
			excludedReason = null;
			refreshPanel();
		}

		// Drop the meeting once its window has fully rotated out.
		if (meeting != null && meeting.rotationEndMs() <= System.currentTimeMillis())
		{
			clearMeeting();
			return;
		}

		if (meeting != null)
		{
			// Record the current world as seen this cycle (boss gender fills in via §3 handler).
			recordCurrentWorld();
		}

		meetingTimers.update(meeting, config, this, markerIcon, despawnIcon());

		// The panel's own 1s ticker keeps the countdowns fresh; a full rebuild is only needed when
		// the world changes (hop list "here" marker and Hop button enablement follow the world).
		int world = client.getWorld();
		if (world != lastWorld)
		{
			lastWorld = world;
			refreshPanel();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		xpRewardLock.onMenuOptionClicked(event);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Resolve the id now rather than inside the lambda, which runs a tick later.
		int groupId = event.getGroupId();
		// Read on the client thread once the widget has populated.
		clientThread.invokeLater(() -> readInterface(groupId));
	}

	/**
	 * Look for the notice board in a freshly loaded interface, whichever one it is.
	 *
	 * <p>Keying off a single interface id was too brittle: every known board message contains the
	 * word "gang", which is also one of the sentinels {@link #readMessageBox} treats as "no meeting".
	 * So if the board ever renders through MESSAGEBOX rather than NOTE, the old dispatch would both
	 * fail to parse the location and clear the meeting it should have set. Matching on the text
	 * instead removes the guess: {@link #BOARD_SENTINEL} appears in all 34 board messages and
	 * nothing else, so an unrelated interface is discarded before the matcher ever sees it.
	 */
	private void readInterface(int groupId)
	{
		List<String> lines = collectBoardText(groupId);

		if (readBoard(groupId, lines))
		{
			return;
		}

		// Only once the text is known not to be a board reading can a message box mean "no meeting".
		if (groupId == InterfaceID.MESSAGEBOX)
		{
			readMessageBox(lines);
		}
	}

	/**
	 * MESSAGEBOX is the generic text dialog used all over the game, so it only means "no meeting"
	 * when it actually carries the notice board's no-intelligence message — an unrelated message
	 * box must not wipe the tracked meeting. Failing closed is cheap: a missed clear self-corrects
	 * on the next board read or when the rotation window lapses.
	 *
	 * <p>Being on-topic is not enough on its own. The Shayzien Encampment is full of dialogue about
	 * the gangs, and the board's own reading contains "gang" too, so a topic word alone would let an
	 * ordinary conversation wipe a meeting that had just been read. A clear needs the message to
	 * also be saying that there is <em>nothing</em>.
	 */
	private void readMessageBox(List<String> lines)
	{
		if (currentMeeting == null)
		{
			return;
		}

		String text = String.join(" ", lines).toLowerCase();
		boolean topical = text.contains("intelligence") || text.contains("gang")
			|| text.contains("noticeboard") || text.contains("notice board");
		if (topical && NO_MEETING.matcher(text).find())
		{
			log.info("Message box reports no gang activity; clearing the meeting: {}", text);
			clearMeeting();
		}
	}

	/**
	 * @return true when the text was a board reading, whether or not it resolved to a location —
	 *     either way it is not a "no meeting" message box.
	 */
	private boolean readBoard(int groupId, List<String> lines)
	{
		if (lines.isEmpty())
		{
			return false;
		}

		String joined = String.join(" ", lines);
		if (!BOARD_SENTINEL.matcher(joined).find())
		{
			return false;
		}

		if (groupId != InterfaceID.NOTE)
		{
			// Worth knowing: the interface the board actually uses was inferred, not confirmed.
			log.info("Notice board text found on interface {}, not the expected {}", groupId, InterfaceID.NOTE);
		}

		NoticeBoardReader.BoardReadResult result = boardReader.read(lines);
		if (result == null)
		{
			log.warn("Interface {} carries notice board text that matched no known location: {}", groupId, joined);
			return true;
		}

		if (config.logRotations())
		{
			rotationLogger.log(result.getLocation().getId());
		}

		// An untracked location still gets its rotation row logged above (the CSV records what was
		// observed, not what was followed) — it just isn't shown or navigated to.
		// This is the one gate between a row reaching rotations.csv and the panel updating, so it
		// says so loudly rather than at debug: from the panel a filtered read is indistinguishable
		// from a parse failure.
		String exclusion = trackingExclusion(result.getLocation());
		if (exclusion != null)
		{
			log.warn("Read a meeting at {} ({}) but the {} setting excludes it, so the panel stays empty",
				result.getLocation().getId(), result.getLocation().getArea(), exclusion);
			// clearMeeting() resets the panel, so record the reason after it and refresh again.
			clearMeeting();
			excludedMeeting = new CurrentMeeting(result.getLocation(), scheduledMs(result), System.currentTimeMillis());
			excludedReason = exclusion;
			refreshPanel();
			return true;
		}

		setMeeting(new CurrentMeeting(result.getLocation(), scheduledMs(result), System.currentTimeMillis()));

		if (!result.isExactMatch())
		{
			log.warn("Notice board matched only fuzzily to {}", result.getLocation().getId());
		}
		return true;
	}

	/** Board countdown resolved to an absolute time; absent means the meeting is already due. */
	private static long scheduledMs(NoticeBoardReader.BoardReadResult result)
	{
		long now = System.currentTimeMillis();
		return result.getMinutesUntil() == null ? now : now + result.getMinutesUntil() * 60_000L;
	}

	private void setMeeting(CurrentMeeting meeting)
	{
		// A meeting we are actually showing supersedes any note about a filtered one.
		excludedMeeting = null;
		excludedReason = null;

		CurrentMeeting previous = currentMeeting;
		OcLocation location = meeting.getLocation();

		// A different location means a new cycle — reset the per-cycle world list and tracked NPCs.
		if (previous == null || !previous.getLocation().getId().equals(location.getId()))
		{
			worldStatuses.clear();
			gangsters.clear();
			bosses.clear();
		}

		activateMeeting(meeting);
		log.debug("Current organised crime meeting: {} ({})", location.getId(), location.getArea());
	}

	/**
	 * Install a meeting as the live one and reconcile every derived display. Shared by the local
	 * board read and by {@link #applyShared}.
	 */
	private void activateMeeting(CurrentMeeting meeting)
	{
		currentMeeting = meeting;
		worldStatuses.computeIfAbsent(client.getWorld(), WorldStatus::new);

		applyWorldMapMarker();
		updateHintArrow();
		routeTo(meeting.getLocation().getWorldPoint());
		meetingTimers.update(meeting, config, this, markerIcon, despawnIcon());
		persist();
		refreshPanel();
	}

	private void clearMeeting()
	{
		currentMeeting = null;
		worldStatuses.clear();
		gangsters.clear();
		bosses.clear();
		worldMapController.clear();
		meetingTimers.clear();
		client.clearHintArrow();
		clearRoute();
		meetingStore.clear();
		refreshPanel();
	}

	/** Record the player's current world for this cycle, persisting only when it's newly seen. */
	private void recordCurrentWorld()
	{
		int world = client.getWorld();
		if (worldStatuses.containsKey(world))
		{
			return;
		}
		worldStatuses.put(world, new WorldStatus(world));
		persist();
	}

	private void persist()
	{
		meetingStore.save(currentMeeting, worldStatuses.values());
	}

	private void refreshPanel()
	{
		if (panel != null)
		{
			panel.refresh();
		}
	}

	/** Whether the tracking filters (area toggles + multicombat-only) include this location. */
	private boolean isTracked(OcLocation location)
	{
		return trackingExclusion(location) == null;
	}

	/**
	 * The name of the setting that excludes this location, or null when it passes. Returning the
	 * reason rather than a bare boolean is what lets a discarded board read explain itself: the
	 * filters are invisible from the panel, so a silent drop looks exactly like a failure to parse.
	 */
	private String trackingExclusion(OcLocation location)
	{
		if (config.multiCombatOnly() && !location.isMulti())
		{
			return "Multicombat only";
		}
		switch (location.getArea())
		{
			case "Arceuus":
				return config.trackArceuus() ? null : "Track Arceuus";
			case "Hosidius":
				return config.trackHosidius() ? null : "Track Hosidius";
			case "Lovakengj":
				return config.trackLovakengj() ? null : "Track Lovakengj";
			case "Piscarilius":
				return config.trackPiscarilius() ? null : "Track Piscarilius";
			case "Shayzien":
				return config.trackShayzien() ? null : "Track Shayzien";
			default:
				return config.trackOther() ? null : "Track Other";
		}
	}

	/** Reconcile the world-map marker with the current meeting and config. */
	private void applyWorldMapMarker()
	{
		CurrentMeeting meeting = currentMeeting;
		if (config.showWorldMapMarker() && meeting != null)
		{
			worldMapController.set(meeting.getLocation(), worldMapIcon);
		}
		else
		{
			worldMapController.clear();
		}
	}

	/** Despawn infobox icon: the intelligence item sprite once fetched, else the plugin badge. */
	private BufferedImage despawnIcon()
	{
		BufferedImage icon = intelIcon;
		return icon != null ? icon : markerIcon;
	}

	private void updateHintArrow()
	{
		CurrentMeeting meeting = currentMeeting;
		if (meeting == null)
		{
			client.clearHintArrow();
			return;
		}

		if (config.showHintArrow() && meeting.getLocation().hasWorldPoint())
		{
			client.setHintArrow(meeting.getLocation().getWorldPoint());
		}
		else
		{
			client.clearHintArrow();
		}
	}

	// ------------------------------------------------------------- Shortest Path (§2)

	/**
	 * Ask the Shortest Path plugin (if installed) to draw a route to the target, via a loose-coupled
	 * {@link PluginMessage}. Debounced on {@link #lastRouted} so an unchanged target doesn't kick off
	 * a pathfinder recompute every tick. If Shortest Path isn't present the message is simply unheard;
	 * the map pin and tile overlay are the always-works fallback.
	 */
	private void routeTo(WorldPoint target)
	{
		if (!config.routeViaShortestPath() || target == null || target.equals(lastRouted))
		{
			return;
		}
		lastRouted = target;
		Map<String, Object> data = new HashMap<>();
		data.put("target", target); // "start" omitted → SP uses the player's location
		// Shortest Path handles this synchronously and reads the player's world location, which
		// asserts the client thread — so post there (callers include startUp and config toggles).
		clientThread.invoke(() -> eventBus.post(new PluginMessage("shortestpath", "path", data)));
	}

	private void clearRoute()
	{
		if (lastRouted == null)
		{
			return;
		}
		lastRouted = null;
		clientThread.invoke(() -> eventBus.post(new PluginMessage("shortestpath", "clear", new HashMap<>())));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!IntelligenceGatheringConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "routeViaShortestPath":
				if (config.routeViaShortestPath())
				{
					CurrentMeeting meeting = currentMeeting;
					if (meeting != null)
					{
						routeTo(meeting.getLocation().getWorldPoint());
					}
				}
				else
				{
					clearRoute();
				}
				break;
			case "showHintArrow":
				// Config changes arrive on the Swing thread; the hint arrow is client state.
				clientThread.invokeLater(this::updateHintArrow);
				break;
			case "showWorldMapMarker":
				applyWorldMapMarker();
				break;
			case "safeWorldsOnly":
				refreshPanel();
				break;
			case "multiCombatOnly":
			case "trackArceuus":
			case "trackHosidius":
			case "trackLovakengj":
			case "trackPiscarilius":
			case "trackShayzien":
			case "trackOther":
			{
				// Tightening a filter drops a now-excluded meeting. Loosening one can't bring a
				// dropped meeting back (its state is gone) — the next board read picks it up.
				CurrentMeeting tracked = currentMeeting;
				if (tracked != null && !isTracked(tracked.getLocation()))
				{
					// clearMeeting touches the hint arrow, which is client state.
					clientThread.invokeLater(this::clearMeeting);
				}
				break;
			}
			default:
				break;
		}
	}

	// ------------------------------------------------------ Boss gender / NPC tracking (§3/§4)

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (currentMeeting == null)
		{
			return;
		}

		NPC npc = event.getNpc();
		int id = npc.getId();
		if (gangIds.isBoss(id))
		{
			bosses.add(npc);
			applyBossGender(gangIds.bossGender(id));
		}
		else if (gangIds.isGangster(id))
		{
			gangsters.add(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		// A tracked boss despawning dead means this world's meeting was cleared. The bosses set is
		// emptied on hop/scene teardown before their despawns arrive, so remove() returning true
		// distinguishes a live-scene despawn from teardown; isDead filters walking-away despawns.
		if (bosses.remove(npc) && npc.isDead() && currentMeeting != null)
		{
			markWorldCleared();
		}
		gangsters.remove(npc);
	}

	/** Mark the player's current world cleared for this cycle (the panel's "done" tag). */
	private void markWorldCleared()
	{
		WorldStatus status = worldStatuses.computeIfAbsent(client.getWorld(), WorldStatus::new);
		status.setLastClearedMs(System.currentTimeMillis());
		persist();
		refreshPanel();
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		if (event.getItem().getId() == ItemID.SHAYZIEN_GANG_INTELLIGENCE)
		{
			intelTiles.add(event.getTile());
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		if (event.getItem().getId() == ItemID.SHAYZIEN_GANG_INTELLIGENCE)
		{
			intelTiles.remove(event.getTile());
		}
	}

	/** Record the gang boss's gender for the player's current world (spec §3). */
	private void applyBossGender(BossGender gender)
	{
		if (gender == BossGender.UNKNOWN)
		{
			return;
		}
		WorldStatus status = worldStatuses.computeIfAbsent(client.getWorld(), WorldStatus::new);
		if (status.getBossGender() != gender)
		{
			status.setBossGender(gender);
			persist();
			refreshPanel();
		}
	}

	/**
	 * Pull all text from the board widget's children. Deliberately scans a range of child
	 * indices and recurses so it does not depend on a specific child layout (spec §3.3).
	 */
	private List<String> collectBoardText(int groupId)
	{
		List<String> out = new ArrayList<>();
		for (int childId = 0; childId < 40; childId++)
		{
			Widget w = client.getWidget(groupId, childId);
			collectText(w, out);
		}
		return out;
	}

	private static void collectText(Widget w, List<String> out)
	{
		if (w == null)
		{
			return;
		}

		String text = w.getText();
		if (text != null && !text.trim().isEmpty())
		{
			out.add(text);
		}

		addChildren(w.getStaticChildren(), out);
		addChildren(w.getDynamicChildren(), out);
		addChildren(w.getNestedChildren(), out);
	}

	private static void addChildren(Widget[] children, List<String> out)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			collectText(child, out);
		}
	}

	@Override
	public String getFilterNotice()
	{
		CurrentMeeting excluded = excludedMeeting;
		String reason = excludedReason;
		if (excluded == null || reason == null || excluded.rotationEndMs() <= System.currentTimeMillis())
		{
			return null;
		}
		return "Read a meeting in " + excluded.getLocation().getArea()
			+ ", but your \"" + reason + "\" setting is hiding it.";
	}

	// ------------------------------------------------------------------ Share codes

	@Override
	public String exportShareCode()
	{
		CurrentMeeting meeting = currentMeeting;
		return meeting == null ? null : shareCode.encode(meeting, worldStatuses.values());
	}

	@Override
	public String importShareCode(String code)
	{
		ShareCode.Decoded decoded;
		try
		{
			decoded = shareCode.decode(code);
		}
		catch (ShareCode.InvalidCodeException e)
		{
			return e.getMessage();
		}

		OcLocation location = decoded.getMeeting().getLocation();
		// The sender's tracking filters are not ours: a shared meeting in an area the user has
		// switched off should say so rather than silently reinstating it.
		if (!isTracked(location))
		{
			return "That meeting is in " + location.getArea() + ", which your tracking filters exclude.";
		}

		clientThread.invoke(() -> applyShared(decoded));
		return null;
	}

	/**
	 * Adopt an imported cycle. An import is an explicit request, so the code's meeting wins outright
	 * rather than being arbitrated against ours — but its world list is merged, not substituted, so
	 * importing never discards scouting the importer did first-hand.
	 */
	private void applyShared(ShareCode.Decoded decoded)
	{
		CurrentMeeting meeting = decoded.getMeeting();
		CurrentMeeting previous = currentMeeting;

		if (previous == null || !previous.getLocation().getId().equals(meeting.getLocation().getId()))
		{
			// A different location means a different cycle — everything we knew belongs to the old one.
			worldStatuses.clear();
			gangsters.clear();
			bosses.clear();
		}

		for (WorldStatus incoming : decoded.getWorlds())
		{
			WorldStatus status = worldStatuses.get(incoming.getWorld());
			if (status == null)
			{
				status = new WorldStatus(incoming.getWorld());
				worldStatuses.put(incoming.getWorld(), status);
			}

			// A gender we watched spawn ourselves outranks a shared one; otherwise fill the blank.
			if (status.getBossGender() == BossGender.UNKNOWN)
			{
				status.setBossGender(incoming.getBossGender());
			}

			// Meetings are not instanced, so someone else's clear consumed that world for us too.
			if (incoming.getLastClearedMs() > status.getLastClearedMs())
			{
				status.setLastClearedMs(incoming.getLastClearedMs());
			}
		}

		activateMeeting(meeting);
		log.debug("Imported meeting {} with {} worlds", meeting.getLocation().getId(), decoded.getWorlds().size());
	}

	// ------------------------------------------------------ IntelligenceGatheringController

	@Override
	public List<WorldStatus> getWorldStatuses()
	{
		return new ArrayList<>(worldStatuses.values());
	}

	@Override
	public int getCurrentWorld()
	{
		return client.getWorld();
	}

	@Override
	public boolean isSafeWorldsOnly()
	{
		return config.safeWorldsOnly();
	}

	@Override
	public void hop(int world)
	{
		worldHopper.hop(world);
	}

	@Provides
	IntelligenceGatheringConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IntelligenceGatheringConfig.class);
	}

	private static BufferedImage buildIcon()
	{
		try
		{
			BufferedImage badge = ImageUtil.loadImageResource(IntelligenceGatheringPlugin.class,
				"/com/tzjakejad/intelligencegathering/gangboss-badge_96.png");
			if (badge != null)
			{
				return badge;
			}
		}
		catch (RuntimeException e)
		{
			// Badge resource missing — fall through to the drawn pin below.
		}

		// Fallback: simple map pin if the badge resource is missing.
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		// Simple map pin.
		g.setColor(new Color(200, 60, 60));
		g.fillOval(3, 1, 10, 10);
		g.setColor(new Color(120, 20, 20));
		g.drawOval(3, 1, 10, 10);
		g.setColor(new Color(200, 60, 60));
		int[] xs = {5, 11, 8};
		int[] ys = {9, 9, 15};
		g.fillPolygon(xs, ys, 3);
		g.setColor(Color.WHITE);
		g.fillOval(6, 4, 4, 4);
		g.dispose();
		return img;
	}
}

package com.tzjakejad.intelligencegathering.board;

import com.tzjakejad.intelligencegathering.model.OcLocation;
import com.tzjakejad.intelligencegathering.model.OcLocations;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

/**
 * Robust notice-board parser (spec §3.3). Takes the raw text pulled from the board widget and
 * resolves it to an {@link OcLocation} plus a countdown, without relying on brittle child
 * indices or an exact {@code .equals()} on an English sentinel string.
 *
 * <p>Matching normalises whitespace and smart quotes on both sides before comparing, then falls
 * back to a best-substring match with a logged warning so a changed Jagex string degrades to a
 * warning instead of throwing.
 */
@Slf4j
@Singleton
public class NoticeBoardReader
{
	// "... in 12 minutes", "... in 1 minute". A board with no countdown (meeting already up)
	// simply yields no match, which callers treat as "starts now".
	private static final Pattern MINUTES = Pattern.compile("(\\d+)\\s*minute", Pattern.CASE_INSENSITIVE);

	private final OcLocations ocLocations;

	/** Normalised board message -> location, built once from the seed set. */
	private final Map<String, OcLocation> byNormalisedMessage;

	@Inject
	public NoticeBoardReader(OcLocations ocLocations)
	{
		this.ocLocations = ocLocations;
		this.byNormalisedMessage = ocLocations.getLocations().stream()
			.collect(Collectors.toMap(
				loc -> normalise(loc.getBoardMessage()),
				Function.identity(),
				(a, b) -> a));
	}

	/**
	 * Parse the collected board text. Returns {@code null} when no location can be resolved at
	 * all (caller should treat as "no meeting"); otherwise a result whose {@code exactMatch}
	 * flag is false when only a fuzzy match was possible.
	 */
	public BoardReadResult read(List<String> boardLines)
	{
		if (boardLines == null || boardLines.isEmpty())
		{
			return null;
		}

		String joined = normalise(String.join(" ", boardLines));

		OcLocation match = byNormalisedMessage.get(joined);
		boolean exact = match != null;

		if (match == null)
		{
			// Substring pass: the location line may be embedded amongst other board text.
			for (Map.Entry<String, OcLocation> e : byNormalisedMessage.entrySet())
			{
				if (joined.contains(e.getKey()))
				{
					match = e.getValue();
					exact = true;
					break;
				}
			}
		}

		if (match == null)
		{
			match = fuzzyMatch(joined);
			if (match != null)
			{
				log.warn("Notice board text did not match any known message exactly; "
					+ "best-guess='{}'. A board string may have changed. Text was: {}",
					match.getId(), joined);
			}
		}

		if (match == null)
		{
			log.warn("Could not resolve notice board text to any location: {}", joined);
			return null;
		}

		return new BoardReadResult(match, exact, parseMinutes(joined));
	}

	/** Token-overlap fallback against the known messages. */
	private OcLocation fuzzyMatch(String normalisedText)
	{
		String[] textTokens = normalisedText.split(" ");
		OcLocation best = null;
		double bestScore = 0.0;

		for (OcLocation loc : ocLocations.getLocations())
		{
			String[] msgTokens = normalise(loc.getBoardMessage()).split(" ");
			int hits = 0;
			for (String mt : msgTokens)
			{
				for (String tt : textTokens)
				{
					if (mt.equals(tt))
					{
						hits++;
						break;
					}
				}
			}
			double score = (double) hits / msgTokens.length;
			if (score > bestScore)
			{
				bestScore = score;
				best = loc;
			}
		}

		// Require a clear majority of tokens to overlap before trusting a fuzzy hit.
		return bestScore >= 0.6 ? best : null;
	}

	private static Integer parseMinutes(String normalisedText)
	{
		Matcher m = MINUTES.matcher(normalisedText);
		if (m.find())
		{
			try
			{
				return Integer.parseInt(m.group(1));
			}
			catch (NumberFormatException ignored)
			{
				// fall through
			}
		}
		return null;
	}

	/**
	 * Collapse whitespace, unify smart quotes/apostrophes and dashes, lowercase for comparison.
	 *
	 * <p>Dashes fold to spaces because the two sides disagree about them: the board writes
	 * "south-west" and "north-eastern" where the seed file spelled them with spaces. Without
	 * this the exact and substring passes both miss and the read falls through to the fuzzy
	 * matcher, which is a coin toss between several near-identical messages in one area.
	 */
	static String normalise(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s
			.replace('’', '\'')   // right single quote
			.replace('‘', '\'')   // left single quote
			.replace('“', '"')    // left double quote
			.replace('”', '"')    // right double quote
			.replace(' ', ' ')    // non-breaking space
			.replace('-', ' ')     // hyphen
			.replace('–', ' ')     // en dash
			.replace('—', ' ')     // em dash
			.replaceAll("\\s+", " ")
			.trim()
			.toLowerCase();
	}

	/** Outcome of a board read. */
	@Value
	public static class BoardReadResult
	{
		OcLocation location;

		/** True for an exact/substring match, false when only a fuzzy match was possible. */
		boolean exactMatch;

		/** Minutes until appearance, or null if not present on the board. */
		Integer minutesUntil;
	}
}

package com.tzjakejad.intelligencegathering.combat;

import com.google.gson.Gson;
import com.tzjakejad.intelligencegathering.model.BossGender;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Registry of gang-boss and gangster NPC ids, loaded from {@code oc-gang-npcs.json} (spec §3/§4).
 *
 * <p>Ids are captured in-game (log {@code npc.getId()}/{@code npc.getName()} at a live meeting) and
 * pasted into the JSON. A boss whose combat style is known goes in {@code maleBossIds} (throwing
 * knives, dangerous) or {@code femaleBossIds} (cutlass/melee, safe); one that's been seen but not yet
 * classified goes in {@code bossIds}, so it is still highlighted while its per-world dot stays
 * {@link BossGender#UNKNOWN} (grey). Nothing is guessed — an unclassified id never marks a world
 * safe or dangerous.
 */
@Slf4j
@Singleton
public class GangIds
{
	private static final String RESOURCE = "/com/tzjakejad/intelligencegathering/oc-gang-npcs.json";

	private final Set<Integer> maleBossIds;
	private final Set<Integer> femaleBossIds;
	private final Set<Integer> bossIds;
	private final Set<Integer> gangsterIds;

	@Inject
	public GangIds(Gson gson)
	{
		Model model = load(gson);
		this.maleBossIds = toSet(model.maleBossIds);
		this.femaleBossIds = toSet(model.femaleBossIds);
		this.bossIds = toSet(model.bossIds);
		this.gangsterIds = toSet(model.gangsterIds);

		int total = maleBossIds.size() + femaleBossIds.size() + bossIds.size() + gangsterIds.size();
		if (total == 0)
		{
			log.debug("No organised crime gang NPC ids seeded yet; boss colouring/highlighting inert");
		}
		else
		{
			log.debug("Loaded gang ids: {} male boss, {} female boss, {} boss (style unknown), {} gangster",
				maleBossIds.size(), femaleBossIds.size(), bossIds.size(), gangsterIds.size());
		}
	}

	/** {@link BossGender} for an NPC id, or {@link BossGender#UNKNOWN} if it isn't a known boss. */
	public BossGender bossGender(int npcId)
	{
		if (maleBossIds.contains(npcId))
		{
			return BossGender.MALE;
		}
		if (femaleBossIds.contains(npcId))
		{
			return BossGender.FEMALE;
		}
		return BossGender.UNKNOWN;
	}

	public boolean isBoss(int npcId)
	{
		return maleBossIds.contains(npcId) || femaleBossIds.contains(npcId) || bossIds.contains(npcId);
	}

	public boolean isGangster(int npcId)
	{
		return gangsterIds.contains(npcId);
	}

	private static Set<Integer> toSet(List<Integer> ids)
	{
		return ids == null ? Collections.emptySet() : new HashSet<>(ids);
	}

	private static Model load(Gson gson)
	{
		try (InputStream in = GangIds.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Gang NPC id file {} not found on classpath", RESOURCE);
				return new Model();
			}

			try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				Model parsed = gson.fromJson(reader, Model.class);
				return parsed == null ? new Model() : parsed;
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to read gang NPC id file", e);
			return new Model();
		}
	}

	/** Maps the JSON shape; unknown keys (e.g. {@code _comment}) are ignored by Gson. */
	private static class Model
	{
		List<Integer> maleBossIds;
		List<Integer> femaleBossIds;
		List<Integer> bossIds;
		List<Integer> gangsterIds;
	}
}

package com.tzjakejad.intelligencegathering.combat;

import com.tzjakejad.intelligencegathering.IntelligenceGatheringConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Collection;
import java.util.Collections;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Highlights dropped Shayzien gang intelligence (the boss drop) on the ground so it's easy to spot
 * in a cramped meeting (spec §4 — the boss "always drops intelligence"). The plugin feeds the live
 * set of tiles the item is sitting on; the colour comes from config. Only tiles on the player's
 * current floor are drawn.
 */
public class GroundItemOverlay extends Overlay
{
	private final Client client;
	private final IntelligenceGatheringConfig config;

	private Supplier<Collection<Tile>> tileSupplier = Collections::emptyList;

	@Inject
	public GroundItemOverlay(Client client, IntelligenceGatheringConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	public void setTileSupplier(Supplier<Collection<Tile>> tileSupplier)
	{
		this.tileSupplier = tileSupplier;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightIntel())
		{
			return null;
		}

		for (Tile tile : tileSupplier.get())
		{
			if (tile == null || tile.getPlane() != client.getPlane())
			{
				continue;
			}

			LocalPoint lp = tile.getLocalLocation();
			if (lp == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, config.intelColor());
			}
		}

		return null;
	}
}

package com.tzjakejad.intelligencegathering.combat;

import com.tzjakejad.intelligencegathering.IntelligenceGatheringConfig;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.util.Collection;
import java.util.Collections;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines tracked gangster NPCs and the gang boss at a meeting (spec §4). The plugin feeds the
 * live NPC sets via suppliers; render style (hull / tile / model outline) and colours come from
 * config. The boss is drawn distinctly with its own colour because it always drops intelligence.
 */
public class NpcHighlightOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 4;

	private final Client client;
	private final IntelligenceGatheringConfig config;
	private final GangIds gangIds;
	private final ModelOutlineRenderer modelOutline;

	private Supplier<Collection<NPC>> gangsterSupplier = Collections::emptyList;
	private Supplier<Collection<NPC>> bossSupplier = Collections::emptyList;

	@Inject
	public NpcHighlightOverlay(Client client, IntelligenceGatheringConfig config, GangIds gangIds,
		ModelOutlineRenderer modelOutline)
	{
		this.client = client;
		this.config = config;
		this.gangIds = gangIds;
		this.modelOutline = modelOutline;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	public void setGangsterSupplier(Supplier<Collection<NPC>> supplier)
	{
		this.gangsterSupplier = supplier;
	}

	public void setBossSupplier(Supplier<Collection<NPC>> supplier)
	{
		this.bossSupplier = supplier;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Only draw for the live scene. During HOPPING/LOADING the tracked NPC references may still
		// hold stale indices from the old scene, so gating here stops their outlines ghosting onto
		// the transition/new world regardless of set contents.
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		if (config.highlightGangsters())
		{
			Color color = config.gangsterColor();
			for (NPC npc : gangsterSupplier.get())
			{
				draw(graphics, npc, color);
			}
		}

		if (config.highlightBoss())
		{
			for (NPC npc : bossSupplier.get())
			{
				draw(graphics, npc, bossColor(npc));
			}
		}

		return null;
	}

	/**
	 * Boss outline colour by danger — red for the knife-throwing (male) boss, green for the melee
	 * (female) boss, and the configurable fallback until a boss's combat style has been seen. Matches
	 * the panel's per-world dot so the two surfaces agree.
	 */
	private Color bossColor(NPC npc)
	{
		if (npc == null)
		{
			return config.bossColor();
		}
		switch (gangIds.bossGender(npc.getId()))
		{
			case MALE:
				return config.bossColorDangerous();
			case FEMALE:
				return config.bossColorSafe();
			default:
				return config.bossColor();
		}
	}

	private void draw(Graphics2D graphics, NPC npc, Color color)
	{
		if (npc == null)
		{
			return;
		}

		switch (config.bossHighlightStyle())
		{
			case HULL:
			{
				Shape hull = npc.getConvexHull();
				if (hull != null)
				{
					OverlayUtil.renderPolygon(graphics, hull, color);
				}
				break;
			}
			case TILE:
			{
				LocalPoint lp = npc.getLocalLocation();
				if (lp != null)
				{
					Polygon tile = Perspective.getCanvasTilePoly(client, lp);
					if (tile != null)
					{
						OverlayUtil.renderPolygon(graphics, tile, color);
					}
				}
				break;
			}
			case OUTLINE:
			default:
				modelOutline.drawOutline(npc, OUTLINE_WIDTH, color, OUTLINE_FEATHER);
				break;
		}
	}
}

package com.tzjakejad.intelligencegathering.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.tzjakejad.intelligencegathering.IntelligenceGatheringConfig;
import com.tzjakejad.intelligencegathering.model.BossGender;
import com.tzjakejad.intelligencegathering.model.CurrentMeeting;
import com.tzjakejad.intelligencegathering.model.OcLocation;
import com.tzjakejad.intelligencegathering.model.OcLocations;
import com.tzjakejad.intelligencegathering.model.WorldStatus;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Persists the current meeting and per-world statuses across restarts (spec §6) by serialising a
 * compact form to the plugin's config group via Gson. Restores only if the saved cycle is still
 * live, so a stale meeting from a previous session is discarded rather than shown.
 */
@Slf4j
@Singleton
public class MeetingStore
{
	private static final String KEY_MEETING = "savedMeeting";
	private static final String KEY_WORLDS = "savedWorlds";
	private static final Type WORLD_LIST = new TypeToken<List<SavedWorld>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;
	private final OcLocations locations;

	@Inject
	public MeetingStore(ConfigManager configManager, Gson gson, OcLocations locations)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.locations = locations;
	}

	public void save(CurrentMeeting meeting, Collection<WorldStatus> worlds)
	{
		if (meeting == null)
		{
			clear();
			return;
		}

		SavedMeeting saved = new SavedMeeting(
			meeting.getLocation().getId(),
			meeting.getScheduledAppearanceMs(),
			meeting.getReadAtMs());
		configManager.setConfiguration(IntelligenceGatheringConfig.GROUP, KEY_MEETING, gson.toJson(saved));

		List<SavedWorld> savedWorlds = new ArrayList<>();
		for (WorldStatus w : worlds)
		{
			savedWorlds.add(new SavedWorld(w.getWorld(), w.getBossGender(), w.getLastClearedMs()));
		}
		configManager.setConfiguration(IntelligenceGatheringConfig.GROUP, KEY_WORLDS, gson.toJson(savedWorlds));
	}

	public void clear()
	{
		configManager.unsetConfiguration(IntelligenceGatheringConfig.GROUP, KEY_MEETING);
		configManager.unsetConfiguration(IntelligenceGatheringConfig.GROUP, KEY_WORLDS);
	}

	/** Restore the saved state, or {@code null} if none / stale / unparseable. */
	public Restored load()
	{
		String meetingJson = configManager.getConfiguration(IntelligenceGatheringConfig.GROUP, KEY_MEETING);
		if (meetingJson == null || meetingJson.isEmpty())
		{
			return null;
		}

		try
		{
			SavedMeeting saved = gson.fromJson(meetingJson, SavedMeeting.class);
			if (saved == null || saved.locationId == null)
			{
				return null;
			}

			OcLocation location = locations.byId(saved.locationId);
			if (location == null)
			{
				log.debug("Saved meeting references unknown location {}", saved.locationId);
				clear();
				return null;
			}

			CurrentMeeting meeting = new CurrentMeeting(location, saved.scheduledAppearanceMs, saved.readAtMs);

			// Discard a meeting whose cycle has already rotated out.
			if (meeting.rotationEndMs() <= System.currentTimeMillis())
			{
				clear();
				return null;
			}

			List<WorldStatus> worlds = new ArrayList<>();
			String worldsJson = configManager.getConfiguration(IntelligenceGatheringConfig.GROUP, KEY_WORLDS);
			if (worldsJson != null && !worldsJson.isEmpty())
			{
				List<SavedWorld> savedWorlds = gson.fromJson(worldsJson, WORLD_LIST);
				if (savedWorlds != null)
				{
					for (SavedWorld sw : savedWorlds)
					{
						WorldStatus ws = new WorldStatus(sw.world);
						ws.setBossGender(sw.bossGender == null ? BossGender.UNKNOWN : sw.bossGender);
						ws.setLastClearedMs(sw.lastClearedMs);
						worlds.add(ws);
					}
				}
			}

			return new Restored(meeting, Collections.unmodifiableList(worlds));
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Failed to parse saved organised crime meeting; clearing", e);
			clear();
			return null;
		}
	}

	@Value
	public static class Restored
	{
		CurrentMeeting meeting;
		List<WorldStatus> worlds;
	}

	private static class SavedMeeting
	{
		final String locationId;
		final long scheduledAppearanceMs;
		final long readAtMs;

		SavedMeeting(String locationId, long scheduledAppearanceMs, long readAtMs)
		{
			this.locationId = locationId;
			this.scheduledAppearanceMs = scheduledAppearanceMs;
			this.readAtMs = readAtMs;
		}
	}

	private static class SavedWorld
	{
		final int world;
		final BossGender bossGender;
		final long lastClearedMs;

		SavedWorld(int world, BossGender bossGender, long lastClearedMs)
		{
			this.world = world;
			this.bossGender = bossGender;
			this.lastClearedMs = lastClearedMs;
		}
	}
}

package com.tzjakejad.intelligencegathering.data;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Appends observed board reads to {@code RUNELITE_DIR/intelligence-gathering/rotations.csv} (spec §5) so
 * the 30-minute rotation order can be reverse-engineered offline. One row per read:
 * {@code utcTimestamp,locationId}. Behind the {@code logRotations} config toggle in the caller.
 */
@Slf4j
@Singleton
public class RotationLogger
{
	private static final Path DIR = RuneLite.RUNELITE_DIR.toPath().resolve("intelligence-gathering");
	private static final Path CSV = DIR.resolve("rotations.csv");
	private static final String HEADER = "utcTimestamp,locationId" + System.lineSeparator();

	/** Append one row for a board read. Best-effort: I/O errors are logged, never thrown. */
	public void log(String locationId)
	{
		if (locationId == null)
		{
			return;
		}

		try
		{
			Files.createDirectories(DIR);
			boolean fresh = !Files.exists(CSV);
			StringBuilder sb = new StringBuilder();
			if (fresh)
			{
				sb.append(HEADER);
			}
			sb.append(Instant.now()).append(',').append(locationId).append(System.lineSeparator());
			Files.write(CSV, sb.toString().getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.CREATE, StandardOpenOption.APPEND);
		}
		catch (IOException e)
		{
			log.warn("Failed to append organised crime rotation row", e);
		}
	}
}

package com.tzjakejad.intelligencegathering.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.tzjakejad.intelligencegathering.model.BossGender;
import com.tzjakejad.intelligencegathering.model.CurrentMeeting;
import com.tzjakejad.intelligencegathering.model.OcLocation;
import com.tzjakejad.intelligencegathering.model.OcLocations;
import com.tzjakejad.intelligencegathering.model.WorldStatus;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

/**
 * Encodes the current meeting and world scouting into a short text code that can be pasted into
 * Discord or a clan chat and imported by someone else's client.
 *
 * <p>Wire format is {@code OCI1-} followed by base64url of gzipped JSON. The prefix names the
 * payload and carries the version, so a future format can be recognised and rejected cleanly rather
 * than parsed into nonsense. Base64url is used because {@code +} and {@code /} do not always survive
 * a round trip through chat clients and URLs; gzip is what keeps a full cycle's worth of worlds
 * inside a single pasteable line.
 *
 * <p>Timestamps are absolute epoch milliseconds and are deliberately <em>not</em> rebased onto the
 * importer's clock. A code can sit on a clipboard for minutes, so elapsed time and clock skew are
 * indistinguishable here — and the plugin already depends on the local clock being roughly right,
 * since that is what its own board reads are stamped with.
 */
@Slf4j
@Singleton
public class ShareCode
{
	private static final String PREFIX = "OCI1-";

	/** Chat clients wrap long lines, and a paste often picks up surrounding whitespace. */
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	private final Gson gson;
	private final OcLocations locations;

	@Inject
	public ShareCode(Gson gson, OcLocations locations)
	{
		this.gson = gson;
		this.locations = locations;
	}

	/** Encode a meeting and its world list. Never returns null. */
	public String encode(CurrentMeeting meeting, Collection<WorldStatus> worlds)
	{
		Payload payload = new Payload();
		payload.locationId = meeting.getLocation().getId();
		payload.scheduledAppearanceMs = meeting.getScheduledAppearanceMs();
		payload.readAtMs = meeting.getReadAtMs();
		payload.worlds = new ArrayList<>();
		for (WorldStatus w : worlds)
		{
			PayloadWorld pw = new PayloadWorld();
			pw.world = w.getWorld();
			pw.bossGender = w.getBossGender();
			pw.lastClearedMs = w.getLastClearedMs();
			payload.worlds.add(pw);
		}

		byte[] json = gson.toJson(payload).getBytes(StandardCharsets.UTF_8);
		return PREFIX + Base64.getUrlEncoder().withoutPadding().encodeToString(gzip(json));
	}

	/**
	 * Decode a pasted code.
	 *
	 * @throws InvalidCodeException with a message meant to be shown to the user
	 */
	public Decoded decode(String text) throws InvalidCodeException
	{
		if (text == null)
		{
			throw new InvalidCodeException("No code to import.");
		}

		String code = WHITESPACE.matcher(text).replaceAll("");
		if (code.isEmpty())
		{
			throw new InvalidCodeException("No code to import.");
		}

		if (!code.startsWith(PREFIX))
		{
			throw new InvalidCodeException(code.startsWith("OCI")
				? "That code is from a newer version of the plugin."
				: "That doesn't look like an Intelligence Gathering code.");
		}

		Payload payload;
		try
		{
			byte[] json = gunzip(Base64.getUrlDecoder().decode(code.substring(PREFIX.length())));
			payload = gson.fromJson(new String(json, StandardCharsets.UTF_8), Payload.class);
		}
		catch (IllegalArgumentException | IOException | JsonSyntaxException e)
		{
			log.debug("Unreadable share code", e);
			throw new InvalidCodeException("That code is damaged — copy it again.");
		}

		if (payload == null || payload.locationId == null)
		{
			throw new InvalidCodeException("That code is damaged — copy it again.");
		}

		OcLocation location = locations.byId(payload.locationId);
		if (location == null)
		{
			throw new InvalidCodeException("That code names a meeting spot this plugin doesn't know.");
		}

		CurrentMeeting meeting = new CurrentMeeting(location, payload.scheduledAppearanceMs, payload.readAtMs);
		if (meeting.rotationEndMs() <= System.currentTimeMillis())
		{
			throw new InvalidCodeException("That code has expired — its meeting has already rotated out.");
		}

		List<WorldStatus> worlds = new ArrayList<>();
		if (payload.worlds != null)
		{
			for (PayloadWorld pw : payload.worlds)
			{
				if (pw == null || pw.world <= 0)
				{
					continue;
				}
				WorldStatus ws = new WorldStatus(pw.world);
				ws.setBossGender(pw.bossGender == null ? BossGender.UNKNOWN : pw.bossGender);
				ws.setLastClearedMs(pw.lastClearedMs);
				worlds.add(ws);
			}
		}

		return new Decoded(meeting, Collections.unmodifiableList(worlds));
	}

	private static byte[] gzip(byte[] raw)
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (GZIPOutputStream gz = new GZIPOutputStream(out))
		{
			gz.write(raw);
		}
		catch (IOException e)
		{
			// Compressing a byte array in memory has no failure mode worth a checked exception.
			throw new IllegalStateException("Failed to compress share code", e);
		}
		return out.toByteArray();
	}

	private static byte[] gunzip(byte[] compressed) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (GZIPInputStream gz = new GZIPInputStream(new ByteArrayInputStream(compressed)))
		{
			byte[] buf = new byte[4096];
			int read;
			while ((read = gz.read(buf)) != -1)
			{
				out.write(buf, 0, read);
			}
		}
		return out.toByteArray();
	}

	@Value
	public static class Decoded
	{
		CurrentMeeting meeting;
		List<WorldStatus> worlds;
	}

	/** Carries a message written for the user, not for a log. */
	public static class InvalidCodeException extends Exception
	{
		public InvalidCodeException(String message)
		{
			super(message);
		}
	}

	private static class Payload
	{
		String locationId;
		long scheduledAppearanceMs;
		long readAtMs;
		List<PayloadWorld> worlds;
	}

	private static class PayloadWorld
	{
		int world;
		BossGender bossGender;
		long lastClearedMs;
	}
}

