package com.tzjakejad.intelligencegathering.model;

import lombok.Value;

/**
 * The single globally-valid meeting for the current cycle (spec §1). One location is live
 * on every world at once, on a 30-minute rotation; gangsters despawn 5 minutes after the
 * scheduled appearance.
 *
 * <p>NOTE: the global-vs-region-scoped assumption is the load-bearing one flagged in spec §1
 * and must be verified in-game.
 */
@Value
public class CurrentMeeting
{
	/** Rotation length: a new location every 30 minutes. */
	public static final long ROTATION_MS = 30 * 60 * 1000L;

	/** Despawn window: gangsters leave 5 minutes after the scheduled appearance. */
	public static final long DESPAWN_MS = 5 * 60 * 1000L;

	/** Location resolved from the board; valid on all worlds. */
	OcLocation location;

	/** Anchor for the 30-min rotation and 5-min despawn timers (epoch ms). */
	long scheduledAppearanceMs;

	/** When the board was read (epoch ms). */
	long readAtMs;

	/** Epoch ms when this location rotates out. */
	public long rotationEndMs()
	{
		return scheduledAppearanceMs + ROTATION_MS;
	}

	/** Epoch ms when the gangsters despawn. */
	public long despawnMs()
	{
		return scheduledAppearanceMs + DESPAWN_MS;
	}
}

package com.tzjakejad.intelligencegathering.model;

import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * One notice-board meeting location. Deserialised from oc-location-anchors.json.
 *
 * <p>{@code boardMessage} is the match key against the in-game notice board (spec §4).
 * {@code worldPoint} coordinates are captured in-game and may be null until seeded;
 * consumers must degrade gracefully when {@link #getWorldPoint()} returns null (spec §3.1).
 */
@Getter
public class OcLocation
{
	/** Stable key, matches the original screenshot basenames, e.g. {@code arceuus1}. */
	private String id;

	/** Arceuus / Hosidius / Lovakengj / Piscarilius / Shayzien / Other. */
	private String area;

	/**
	 * Multicombat flag, per the wiki's Meeting locations table. Only the four Port Piscarilius
	 * spots (foodhall, behind the foodhall, western pier, south-west pier) are single-way.
	 */
	private boolean multi;

	/** Floor: 0 ground, 1 upstairs/middle. Inferred from the description; verify in-game. */
	private int plane;

	/** Nullable coordinates from the seed file. */
	private Coord worldPoint;

	/** Exact notice-board string; the match key. */
	private String boardMessage;

	/** Human-readable directions carried over from the original plugin. */
	private String navHint;

	/**
	 * Resolved RuneLite world point at this location's plane, or {@code null} if the
	 * coordinate has not been captured yet.
	 */
	public WorldPoint getWorldPoint()
	{
		if (worldPoint == null || worldPoint.x == null || worldPoint.y == null)
		{
			return null;
		}
		return new WorldPoint(worldPoint.x, worldPoint.y, plane);
	}

	public boolean hasWorldPoint()
	{
		return getWorldPoint() != null;
	}

	/** Raw nullable x/y as stored in the seed JSON. */
	public static class Coord
	{
		public Integer x;
		public Integer y;
	}
}

package com.tzjakejad.intelligencegathering.model;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the 34 meeting locations from {@code oc-location-anchors.json} on the classpath
 * (spec §5). Replaces the original hardcoded 316-line locations class with data.
 */
@Slf4j
@Singleton
public class OcLocations
{
	private static final String RESOURCE = "/com/tzjakejad/intelligencegathering/oc-location-anchors.json";

	@Getter
	private final List<OcLocation> locations;

	private final Map<String, OcLocation> byId;

	@Inject
	public OcLocations(Gson gson)
	{
		this.locations = load(gson);
		this.byId = locations.stream()
			.collect(Collectors.toMap(OcLocation::getId, Function.identity()));
		log.debug("Loaded {} organised crime locations", locations.size());
	}

	private static List<OcLocation> load(Gson gson)
	{
		try (InputStream in = OcLocations.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Seed file {} not found on classpath", RESOURCE);
				return Collections.emptyList();
			}

			Type type = new TypeToken<List<OcLocation>>()
			{
			}.getType();

			try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				List<OcLocation> parsed = gson.fromJson(reader, type);
				return parsed == null ? Collections.emptyList() : Collections.unmodifiableList(parsed);
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to read organised crime seed file", e);
			return Collections.emptyList();
		}
	}

	public OcLocation byId(String id)
	{
		return byId.get(id);
	}
}

