package com.tzjakejad.intelligencegathering.nav;

import com.tzjakejad.intelligencegathering.IntelligenceGatheringConfig;
import com.tzjakejad.intelligencegathering.model.CurrentMeeting;
import com.tzjakejad.intelligencegathering.model.OcLocation;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws the scene-tile highlight for the current meeting when the player is on the spawn's floor
 * and the tile is inside the loaded scene (spec §3.2). Long-range guidance to the meeting is the
 * game hint arrow (handled in the plugin), not a scene overlay.
 */
public class SceneOverlay extends Overlay
{
	private final Client client;
	private final IntelligenceGatheringConfig config;

	/** Supplies the live current meeting; set by the plugin at start-up. */
	private Supplier<CurrentMeeting> meetingSupplier = () -> null;

	@Inject
	public SceneOverlay(Client client, IntelligenceGatheringConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	public void setMeetingSupplier(Supplier<CurrentMeeting> meetingSupplier)
	{
		this.meetingSupplier = meetingSupplier;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		CurrentMeeting meeting = meetingSupplier.get();
		if (meeting == null)
		{
			return null;
		}

		OcLocation location = meeting.getLocation();
		WorldPoint wp = location.getWorldPoint();
		if (wp == null || client.getPlane() != location.getPlane())
		{
			return null;
		}

		LocalPoint lp = LocalPoint.fromWorld(client, wp);
		if (lp == null)
		{
			// Outside the loaded scene / wrong region — nothing to draw here.
			return null;
		}

		if (config.showTileHighlight())
		{
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, config.tileColor());
			}
		}

		return null;
	}
}

package com.tzjakejad.intelligencegathering.nav;

import com.tzjakejad.intelligencegathering.model.OcLocation;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Owns the single world-map marker for the current meeting (spec §3.1). Degrades gracefully:
 * a location with no captured {@link OcLocation#getWorldPoint()} simply gets no marker.
 */
@Singleton
public class WorldMapController
{
	private final WorldMapPointManager worldMapPointManager;

	private WorldMapPoint current;

	@Inject
	public WorldMapController(WorldMapPointManager worldMapPointManager)
	{
		this.worldMapPointManager = worldMapPointManager;
	}

	/** Show the marker for a location, replacing any existing one. No-op if coord is unknown. */
	public void set(OcLocation location, BufferedImage icon)
	{
		clear();

		WorldPoint wp = location.getWorldPoint();
		if (wp == null)
		{
			return;
		}

		// Snapshot the (async item) image onto a plain ARGB image so the world map draws it reliably,
		// the way the clue scroll plugin composites its map icon.
		BufferedImage image = flatten(icon);

		String tooltip = location.getArea() + ": " + location.getNavHint();
		current = WorldMapPoint.builder()
			.worldPoint(wp)
			.image(image)
			.tooltip(tooltip)
			.name("Intelligence Gathering")
			.jumpOnClick(true)
			.build();
		// Snap to the map edge when the meeting is off the visible map, so it's always findable when
		// you open the map from a distance — this is the clue-scroll behaviour.
		current.setSnapToEdge(true);
		if (image != null)
		{
			current.setImagePoint(new Point(image.getWidth() / 2, image.getHeight() / 2));
		}

		worldMapPointManager.add(current);
	}

	/** Copy onto a plain image; an {@code AsyncBufferedImage} isn't always drawn on the world map. */
	private static BufferedImage flatten(BufferedImage src)
	{
		if (src == null || src.getWidth() <= 0 || src.getHeight() <= 0)
		{
			return src;
		}
		BufferedImage flat = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics g = flat.getGraphics();
		g.drawImage(src, 0, 0, null);
		g.dispose();
		return flat;
	}

	public void clear()
	{
		if (current != null)
		{
			worldMapPointManager.remove(current);
			current = null;
		}
	}
}

package com.tzjakejad.intelligencegathering.rewards;

import com.tzjakejad.intelligencegathering.IntelligenceGatheringConfig;
import com.tzjakejad.intelligencegathering.IntelligenceGatheringConfig.RewardSkill;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Misclick guard for the reward XP dialog: swallows clicks on skills the player has not
 * allowed, so a stray click on "Attack" can't ruin a defence pure.
 *
 * <p>The reward chooser is an ordinary chatbox option list ({@link InterfaceID.Chatmenu}), so the
 * guard has to be narrow or it would eat clicks in unrelated dialogues. Two conditions must both
 * hold before anything is touched: the option list carries the dialog's own title, and the clicked
 * option reads as {@code "<skill>: <xp>"}. Anything else is left completely alone.
 */
@Slf4j
@Singleton
public class XpRewardLock
{
	/** Title the reward chooser opens with; the only dialog this class acts on. */
	private static final String DIALOG_TITLE = "what kind of training will you pursue?";

	/** Prepended to locked option text so the dialog reads as disabled rather than dead. */
	private static final String STRIKETHROUGH = "<str>";

	private final Client client;
	private final IntelligenceGatheringConfig config;

	@Inject
	public XpRewardLock(Client client, IntelligenceGatheringConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/** Swallow the click when it lands on a locked skill. */
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.lockXpReward() || event.getParam1() != InterfaceID.Chatmenu.OPTIONS)
		{
			return;
		}

		Widget[] options = rewardOptions();
		if (options == null)
		{
			return;
		}

		int index = event.getParam0();
		if (index < 0 || index >= options.length)
		{
			return;
		}

		RewardSkill skill = optionSkill(options[index]);
		if (skill != null && !allowedSkills().contains(skill))
		{
			log.debug("Blocked reward XP click on {}", skill);
			event.consume();
		}
	}

	/**
	 * Strike through the locked options so the block is visible. Driven from the game tick, which
	 * is only a redraw delay — {@link #onMenuOptionClicked} guards the click on its own.
	 */
	public void markLockedOptions()
	{
		if (!config.lockXpReward())
		{
			return;
		}

		Widget[] options = rewardOptions();
		if (options == null)
		{
			return;
		}

		Set<RewardSkill> allowed = allowedSkills();
		for (Widget option : options)
		{
			RewardSkill skill = optionSkill(option);
			if (skill == null || allowed.contains(skill))
			{
				continue;
			}

			String text = option.getText();
			if (!text.startsWith(STRIKETHROUGH))
			{
				option.setText(STRIKETHROUGH + text);
			}
		}
	}

	/**
	 * Dynamic children of the chatbox option list, but only while it is showing the reward
	 * chooser. Null for every other dialog, which is what keeps the guard from overreaching.
	 */
	private Widget[] rewardOptions()
	{
		Widget list = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		if (list == null || list.isHidden())
		{
			return null;
		}

		Widget[] children = list.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return null;
		}

		for (Widget child : children)
		{
			if (clean(child.getText()).equals(DIALOG_TITLE))
			{
				return children;
			}
		}

		return null;
	}

	/**
	 * The skill an option awards, or null when the text isn't a {@code "<skill>: <xp>"} row naming
	 * one of the four dialog skills. The title, any cancel row, and anything unrecognised all land
	 * here and are left clickable — an option the allowlist can't express must never be blocked.
	 */
	private static RewardSkill optionSkill(Widget option)
	{
		String text = clean(option.getText());
		int colon = text.indexOf(':');
		if (colon <= 0)
		{
			return null;
		}

		String name = text.substring(0, colon).trim();
		for (RewardSkill skill : RewardSkill.values())
		{
			if (skill.name().toLowerCase(Locale.ROOT).equals(name))
			{
				return skill;
			}
		}

		return null;
	}

	/**
	 * Configured allowlist. An empty selection blocks all four: the point of the guard is
	 * protection, so the safe failure is refusing a click, not quietly permitting every one.
	 */
	private Set<RewardSkill> allowedSkills()
	{
		Set<RewardSkill> configured = config.allowedXpSkills();
		return configured == null ? EnumSet.noneOf(RewardSkill.class) : configured;
	}

	private static String clean(String text)
	{
		return text == null ? "" : Text.removeTags(text).trim().toLowerCase(Locale.ROOT);
	}
}

package com.tzjakejad.intelligencegathering.timer;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.function.LongSupplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * A generic mm:ss countdown infobox towards a target epoch-ms supplied lazily, so it keeps
 * ticking without needing per-frame updates pushed into it (spec §3.4).
 */
class CountdownInfoBox extends InfoBox
{
	private final LongSupplier targetMs;
	private final boolean redWhenLow;

	CountdownInfoBox(BufferedImage image, Plugin plugin, String tooltip, LongSupplier targetMs,
		boolean redWhenLow)
	{
		super(image, plugin);
		this.targetMs = targetMs;
		this.redWhenLow = redWhenLow;
		setTooltip(tooltip);
	}

	private long remainingMs()
	{
		return Math.max(0, targetMs.getAsLong() - System.currentTimeMillis());
	}

	@Override
	public String getText()
	{
		long totalSeconds = remainingMs() / 1000L;
		long minutes = totalSeconds / 60;
		long seconds = totalSeconds % 60;
		return String.format("%d:%02d", minutes, seconds);
	}

	@Override
	public Color getTextColor()
	{
		if (redWhenLow && remainingMs() <= 60_000L)
		{
			return Color.RED;
		}
		return Color.WHITE;
	}
}

package com.tzjakejad.intelligencegathering.timer;

import com.tzjakejad.intelligencegathering.IntelligenceGatheringConfig;
import com.tzjakejad.intelligencegathering.model.CurrentMeeting;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

/**
 * Manages the two meeting infoboxes (spec §3.4), both derived from
 * {@link CurrentMeeting#getScheduledAppearanceMs()}:
 *
 * <ul>
 *   <li><b>Meeting start</b> — counts down to the gangsters appearing, matching the board's
 *       "in X minutes" line.</li>
 *   <li><b>Despawn</b> — counts down the 5-minute active window; red under 60s.</li>
 * </ul>
 */
@Singleton
public class MeetingTimers
{
	private final InfoBoxManager infoBoxManager;

	private CountdownInfoBox rotationBox;
	private CountdownInfoBox despawnBox;

	// Persisted boxes read their target from here rather than capturing a single CurrentMeeting.
	// Re-reading the board mints a fresh instance with a recomputed anchor (it tracks the board's
	// whole-minute "in X minutes" line); without this the reused infoboxes would keep counting to
	// the first read's stale anchor and drift out of step with the side panel.
	private volatile CurrentMeeting meeting;

	@Inject
	public MeetingTimers(InfoBoxManager infoBoxManager)
	{
		this.infoBoxManager = infoBoxManager;
	}

	/**
	 * Reconcile the infoboxes with the current meeting and config. Safe to call repeatedly.
	 */
	public void update(CurrentMeeting meeting, IntelligenceGatheringConfig config, Plugin plugin,
		BufferedImage rotationIcon, BufferedImage despawnIcon)
	{
		this.meeting = meeting;

		if (meeting == null)
		{
			clear();
			return;
		}

		long now = System.currentTimeMillis();

		// Meeting-start timer: counts down to the gangsters appearing, so it reads the same as the
		// board's "in X minutes" line (not the +30-minute rotation end, which confusingly overshot).
		boolean wantStart = config.showRotationTimer() && meeting.getScheduledAppearanceMs() > now;
		if (wantStart && rotationBox == null)
		{
			rotationBox = new CountdownInfoBox(rotationIcon, plugin,
				"Organised crime meeting starts", this::spawnTargetMs, false);
			infoBoxManager.addInfoBox(rotationBox);
		}
		else if (!wantStart && rotationBox != null)
		{
			removeRotation();
		}

		// Despawn timer: only once the meeting is live and its 5-minute window is still open.
		boolean live = now >= meeting.getScheduledAppearanceMs();
		boolean wantDespawn = config.showDespawnTimer() && live && meeting.despawnMs() > now;
		if (wantDespawn && despawnBox == null)
		{
			despawnBox = new CountdownInfoBox(despawnIcon, plugin,
				"Gangsters despawn", this::despawnTargetMs, true);
			infoBoxManager.addInfoBox(despawnBox);
		}
		else if (!wantDespawn && despawnBox != null)
		{
			removeDespawn();
		}
	}

	private long spawnTargetMs()
	{
		CurrentMeeting m = meeting;
		return m == null ? System.currentTimeMillis() : m.getScheduledAppearanceMs();
	}

	private long despawnTargetMs()
	{
		CurrentMeeting m = meeting;
		return m == null ? System.currentTimeMillis() : m.despawnMs();
	}

	public void clear()
	{
		removeRotation();
		removeDespawn();
	}

	private void removeRotation()
	{
		if (rotationBox != null)
		{
			infoBoxManager.removeInfoBox(rotationBox);
			rotationBox = null;
		}
	}

	private void removeDespawn()
	{
		if (despawnBox != null)
		{
			infoBoxManager.removeInfoBox(despawnBox);
			despawnBox = null;
		}
	}
}

package com.tzjakejad.intelligencegathering.ui;

import com.tzjakejad.intelligencegathering.model.CurrentMeeting;
import com.tzjakejad.intelligencegathering.model.WorldStatus;
import java.util.List;

/**
 * Read/act surface the {@link IntelligenceGatheringPanel} uses, keeping the Swing panel decoupled from
 * the plugin's event wiring.
 */
public interface IntelligenceGatheringController
{
	CurrentMeeting getCurrentMeeting();

	/** Worlds visited this cycle, sorted for display. */
	List<WorldStatus> getWorldStatuses();

	int getCurrentWorld();

	boolean isSafeWorldsOnly();

	void hop(int world);

	/**
	 * Why the panel is empty even though a notice board was read successfully, or null when there is
	 * no such explanation. A meeting discarded by the tracking filters is otherwise indistinguishable
	 * from one that never parsed.
	 */
	String getFilterNotice();

	/** Share code for the current cycle, or null when there is no meeting to share. */
	String exportShareCode();

	/**
	 * Apply a pasted share code.
	 *
	 * @return null once the import is under way, or a message to show the user if the code was
	 *     rejected. Validation is synchronous so the panel can report the reason immediately; the
	 *     state change itself is handed to the client thread.
	 */
	String importShareCode(String code);
}

